\STATE $l_{\rm min}\! = \! \arg \min\limits_{\widetilde l} \left\{ \sum\nolimits_{p=1}^{P}
 \left\| \left[ {\bf c}_p \right]_{\widetilde l} \right\|_2^2 , {\widetilde l} \in \Omega \right\}$.
 {\scriptsize \%~Find the support of the minimum average energy according to the estimated~${\bf c}_p$.}
\IF {$\sum\nolimits_{p=1}^{P} \left\| \left[ {\bf c}_p \right]_{l_{\min}}
