    \STATE {Quit iteration.} {\scriptsize \%~Support index associated with AWGN may be included~in~$\Omega$.}
\ELSIF{$\sum\nolimits_{p=1}^{P} \left\| {\bf b}_p^{\rm{last}} \right\|_2^2  < \sum\nolimits_{p=1}^{P}
 \left\| {\bf b}_p \right\|_2^2$}
    \STATE {Quit iteration.} {\scriptsize \%~Larger~residual~of~the current~stage~than that of the
