\ELSIF{$\sum\nolimits_{p=1}^{P} \left\| {\bf b}_p^{i-1} \right\|_2^2 \le \sum\nolimits_{p=1}^{P}
 \left\| {\bf b}_p \right\|_2^2$}
     \STATE $j \!\!= \!\!j\!+\!1$; ${\cal{T}}\!\! = \!\!j$; ${\bf c}_p^{\rm{last}}
