 {\scriptsize \%~Begin a new stage. The larger residual of current iteration than that of last
 iteration indicates that iteration at current stage~converges.}
\ELSE
    \STATE ${\Omega}^i = {\Omega}$; ${\bf b}_p^i = {\bf b}_p$, $\forall p$; $i  = i+1$.
 {\scriptsize \%~Continue the iteration at the current stage.}
\ENDIF
\UNTIL{$\sum\nolimits_{p=1}^{P} \left\| \left[ {\bf c}_p \right]_{l_{\min}} \right\|_2^2 / {P}
